import authSchema from "./auth-schema.sql?raw";
import type { Env, Install, Mode, Workspace } from "./types";

let ready: Promise<void> | null = null;
export function ensurePlatform(env: Env) {
  ready ??= (async () => {
    const db = env.PLATFORM_DB;
    // Better Auth's tables, generated by scripts/auth-schema.ts. Idempotent: every statement becomes IF NOT EXISTS.
    const statements = authSchema.split(";").map((s) => s.replace(/^--.*$/gm, "").trim()).filter(Boolean)
      .map((s) => s.replace(/^create table "/i, 'create table if not exists "').replace(/^create (unique )?index "/i, 'create $1index if not exists "'));
    await db.batch(statements.map((s) => db.prepare(s)));
    await db.prepare(`CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, token TEXT NOT NULL, provider TEXT NOT NULL DEFAULT 'plain', created_at TEXT NOT NULL DEFAULT (datetime('now')))`).run();
    await db.prepare(`CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)`).run();
    await db.prepare(`CREATE TABLE IF NOT EXISTS installs (workspace_id TEXT NOT NULL, app_id TEXT NOT NULL, name TEXT NOT NULL, version TEXT NOT NULL, worker TEXT NOT NULL, repo TEXT, mount TEXT, upstream TEXT, installed_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY (workspace_id, app_id))`).run();
    const cols = (await db.prepare("PRAGMA table_info(workspaces)").all<{ name: string }>()).results.map((c) => c.name);
    for (const [col, type] of [["repo", "TEXT"], ["organization_id", "TEXT"], ["team_id", "TEXT"], ["worker", "TEXT"], ["d1_id", "TEXT"], ["version", "TEXT"], ["contract", "INTEGER"]]) {
      if (!cols.includes(col)) await db.prepare(`ALTER TABLE workspaces ADD COLUMN ${col} ${type}`).run();
    }
    const installCols = (await db.prepare("PRAGMA table_info(installs)").all<{ name: string }>()).results.map((c) => c.name);
    for (const [col, type] of [["route", "TEXT"], ["commit_sha", "TEXT"], ["status", "TEXT"]]) {
      if (!installCols.includes(col)) await db.prepare(`ALTER TABLE installs ADD COLUMN ${col} ${type}`).run();
    }
    await db.prepare(`CREATE TABLE IF NOT EXISTS update_log (id TEXT PRIMARY KEY, part TEXT NOT NULL, target TEXT NOT NULL, from_version TEXT, to_version TEXT NOT NULL, status TEXT NOT NULL, detail TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')))`).run();
    const s = env.SEED_WORKSPACE;
    if (s) await db.prepare("INSERT OR IGNORE INTO workspaces (id, name, url, token) VALUES (?, ?, ?, ?)").bind(s.id, s.name, s.url, s.token).run();
  })().catch((e) => { ready = null; throw e; });
  return ready;
}

export const listWorkspaces = (env: Env) => env.PLATFORM_DB.prepare("SELECT * FROM workspaces ORDER BY created_at").all<Workspace>().then((r) => r.results);
export const listWorkspacesIn = (env: Env, orgIds: string[]) => orgIds.length
  ? env.PLATFORM_DB.prepare(`SELECT * FROM workspaces WHERE organization_id IN (${orgIds.map(() => "?").join(",")}) ORDER BY created_at`).bind(...orgIds).all<Workspace>().then((r) => r.results)
  : Promise.resolve([] as Workspace[]);
export const getWorkspace = (env: Env, id: string) => env.PLATFORM_DB.prepare("SELECT * FROM workspaces WHERE id = ?").bind(id).first<Workspace>();
export async function createWorkspace(env: Env, w: { id: string; name: string; url: string; token: string; repo?: string | null; organization_id?: string | null; worker?: string; d1_id?: string; version?: string; contract?: number }) {
  await env.PLATFORM_DB.prepare(`INSERT INTO workspaces (id, name, url, token, repo, organization_id, worker, d1_id, version, contract) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET name = excluded.name, url = excluded.url, token = excluded.token, repo = COALESCE(excluded.repo, workspaces.repo), organization_id = COALESCE(excluded.organization_id, workspaces.organization_id)`)
    .bind(w.id, w.name, w.url, w.token, w.repo ?? null, w.organization_id ?? null, w.worker ?? null, w.d1_id ?? null, w.version ?? null, w.contract ?? null).run();
}
export const setWorkspaceRelease = (env: Env, id: string, version: string, contract: number) => env.PLATFORM_DB.prepare("UPDATE workspaces SET version = ?, contract = ? WHERE id = ?").bind(version, contract, id).run();
export const setWorkspaceTeam = (env: Env, id: string, teamId: string | null) => env.PLATFORM_DB.prepare("UPDATE workspaces SET team_id = ? WHERE id = ?").bind(teamId, id).run();
/** Workspaces registered before accounts existed get the first organization. */
export const adoptOrphanWorkspaces = (env: Env, orgId: string) => env.PLATFORM_DB.prepare("UPDATE workspaces SET organization_id = ? WHERE organization_id IS NULL").bind(orgId).run();
export const listInstalls = (env: Env, ws: string) => env.PLATFORM_DB.prepare("SELECT * FROM installs WHERE workspace_id = ? ORDER BY installed_at").bind(ws).all<Install>().then((r) => r.results);
export async function upsertInstall(env: Env, i: Omit<Install, "installed_at" | "updated_at" | "route" | "commit_sha" | "status"> & Partial<Pick<Install, "route" | "commit_sha" | "status">>) {
  await env.PLATFORM_DB.prepare(`INSERT INTO installs (workspace_id, app_id, name, version, worker, repo, mount, upstream, route, commit_sha, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(workspace_id, app_id) DO UPDATE SET name = excluded.name, version = excluded.version, worker = excluded.worker, repo = excluded.repo, mount = excluded.mount, upstream = excluded.upstream, route = COALESCE(excluded.route, installs.route), commit_sha = COALESCE(excluded.commit_sha, installs.commit_sha), status = COALESCE(excluded.status, installs.status), updated_at = datetime('now')`)
    .bind(i.workspace_id, i.app_id, i.name, i.version, i.worker, i.repo, i.mount, i.upstream, i.route ?? null, i.commit_sha ?? null, i.status ?? null).run();
}
export const listAllInstalls = (env: Env) => env.PLATFORM_DB.prepare("SELECT * FROM installs ORDER BY workspace_id, installed_at").all<Install>().then((r) => r.results);
export const setInstallRelease = (env: Env, ws: string, app: string, f: { version: string; commit_sha: string | null; status: string | null }) =>
  env.PLATFORM_DB.prepare("UPDATE installs SET version = ?, commit_sha = COALESCE(?, commit_sha), status = ?, updated_at = datetime('now') WHERE workspace_id = ? AND app_id = ?").bind(f.version, f.commit_sha, f.status, ws, app).run();
export type UpdateLog = { id: string; part: string; target: string; from_version: string | null; to_version: string; status: string; detail: string | null; created_at: string };
export const logUpdate = (env: Env, l: Omit<UpdateLog, "id" | "created_at">) =>
  env.PLATFORM_DB.prepare("INSERT INTO update_log (id, part, target, from_version, to_version, status, detail) VALUES (?, ?, ?, ?, ?, ?, ?)").bind(crypto.randomUUID(), l.part, l.target, l.from_version, l.to_version, l.status, l.detail).run();
export const listUpdateLog = (env: Env, limit = 20) => env.PLATFORM_DB.prepare("SELECT * FROM update_log ORDER BY created_at DESC LIMIT ?").bind(limit).all<UpdateLog>().then((r) => r.results);
export const removeInstall = (env: Env, ws: string, app: string) => env.PLATFORM_DB.prepare("DELETE FROM installs WHERE workspace_id = ? AND app_id = ?").bind(ws, app).run();
export async function getSetting<T>(env: Env, key: string, fallback: T): Promise<T> {
  const row = await env.PLATFORM_DB.prepare("SELECT value FROM settings WHERE key = ?").bind(key).first<{ value: string }>();
  return row ? (JSON.parse(row.value) as T) : fallback;
}
export const setSetting = (env: Env, key: string, value: unknown) =>
  env.PLATFORM_DB.prepare("INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value").bind(key, JSON.stringify(value)).run();

export const getMode = (env: Env) => getSetting<Mode>(env, "mode", env.SG_MODE ?? "creator");
export const userCount = (env: Env) => env.PLATFORM_DB.prepare('SELECT COUNT(*) AS n FROM "user"').first<{ n: number }>().then((r) => r?.n ?? 0);

// Reads of Better Auth's tables the platform needs for its own screens. Writes go through auth.api.
export type Org = { id: string; name: string; slug: string; createdAt: string };
export type Membership = { organizationId: string; role: string; name: string; slug: string };
export const listMemberships = (env: Env, userId: string) =>
  env.PLATFORM_DB.prepare('SELECT m.organizationId, m.role, o.name, o.slug FROM "member" m JOIN "organization" o ON o.id = m.organizationId WHERE m.userId = ? ORDER BY o.createdAt').bind(userId).all<Membership>().then((r) => r.results);
export const listOrgs = (env: Env) => env.PLATFORM_DB.prepare('SELECT id, name, slug, createdAt FROM "organization" ORDER BY createdAt').all<Org>().then((r) => r.results);
export const getOrg = (env: Env, id: string) => env.PLATFORM_DB.prepare('SELECT id, name, slug, createdAt FROM "organization" WHERE id = ?').bind(id).first<Org>();
export const getOrgBySlug = (env: Env, slug: string) => env.PLATFORM_DB.prepare('SELECT id, name, slug, createdAt FROM "organization" WHERE slug = ?').bind(slug).first<Org>();
export const listTeams = (env: Env, orgId: string) => env.PLATFORM_DB.prepare('SELECT id, name FROM "team" WHERE organizationId = ? ORDER BY createdAt').bind(orgId).all<{ id: string; name: string }>().then((r) => r.results);
export const userTeamIds = (env: Env, userId: string, orgId: string) =>
  env.PLATFORM_DB.prepare('SELECT t.id FROM "teamMember" tm JOIN "team" t ON t.id = tm.teamId WHERE tm.userId = ? AND t.organizationId = ?').bind(userId, orgId).all<{ id: string }>().then((r) => r.results.map((x) => x.id));
export const getCustomRole = (env: Env, orgId: string, role: string) =>
  env.PLATFORM_DB.prepare('SELECT permission FROM "organizationRole" WHERE organizationId = ? AND role = ?').bind(orgId, role).first<{ permission: string }>();
export const listPendingInvitations = (env: Env, orgId: string) =>
  env.PLATFORM_DB.prepare('SELECT id, email, role, teamId, expiresAt FROM "invitation" WHERE organizationId = ? AND status = ? ORDER BY createdAt DESC').bind(orgId, "pending").all<{ id: string; email: string; role: string | null; teamId: string | null; expiresAt: string }>().then((r) => r.results);
export const pendingInvitationFor = (env: Env, email: string) =>
  env.PLATFORM_DB.prepare('SELECT id FROM "invitation" WHERE lower(email) = lower(?) AND status = ? AND expiresAt > ? LIMIT 1').bind(email, "pending", new Date().toISOString()).first<{ id: string }>();
export const orgCounts = (env: Env) => env.PLATFORM_DB.prepare('SELECT (SELECT COUNT(*) FROM "organization") AS orgs, (SELECT COUNT(*) FROM "team") AS teams, (SELECT COUNT(*) FROM "organizationRole") AS customRoles').first<{ orgs: number; teams: number; customRoles: number }>();
